// Package esphome is an ESPHome native API server: Home Assistant connects
// to the Echo itself, as it does to a Voice PE, instead of to the controller
// that presents each Echo today (controller/em_esphome.py, whose handshake,
// device info and entities this follows). The messages are aioesphomeapi's
// (internal/esphome/api, generated by tools/esphome_gen).
//
// It is pure Go and hardware-free: what an Echo has (its entities) is
// handed to it by the firmware, from the board's data, so it serves any Echo
// as it is.
package esphome

import (
	"bufio"
	"errors"
	"fmt"
	"io"
)

// The plaintext frame (frame_protocol.py encode_frame): a zero byte, the
// payload length and the message type as varuints, then the payload.
// Several frames may share one write.

const (
	plaintextPreamble = 0x00
	noisePreamble     = 0x01
	// maxVaruintBytes bounds a length or a type (frame_protocol.py
	// _MAX_VARUINT_BYTES): a longer one is not a frame.
	maxVaruintBytes = 5
	// MaxPayload bounds one message. The largest the Echo is sent are
	// HA's media player commands and Bluetooth writes, far below it.
	MaxPayload = 64 * 1024
)

var (
	// ErrNoise is a client speaking the encrypted protocol to a server that
	// has no key: ESPHome's own answer is to close.
	ErrNoise     = errors.New("esphome: encrypted client, no key configured")
	errPreamble  = errors.New("esphome: not a frame")
	errVaruint   = errors.New("esphome: varuint too long")
	errTooLarge  = errors.New("esphome: frame too large")
	errNegative  = errors.New("esphome: negative varuint")
	errTruncated = io.ErrUnexpectedEOF
)

func readVaruint(r *bufio.Reader) (uint32, error) {
	var v uint32
	for i := 0; i < maxVaruintBytes; i++ {
		b, err := r.ReadByte()
		if err != nil {
			if i > 0 && err == io.EOF {
				return 0, errTruncated
			}
			return 0, err
		}
		v |= uint32(b&0x7f) << (7 * i)
		if b&0x80 == 0 {
			return v, nil
		}
	}
	return 0, errVaruint
}

// ReadFrame reads one plaintext frame.
func ReadFrame(r *bufio.Reader) (typ uint32, payload []byte, err error) {
	p, err := r.ReadByte()
	if err != nil {
		return 0, nil, err
	}
	switch p {
	case plaintextPreamble:
	case noisePreamble:
		return 0, nil, ErrNoise
	default:
		return 0, nil, fmt.Errorf("%w: preamble %#x", errPreamble, p)
	}
	n, err := readVaruint(r)
	if err != nil {
		return 0, nil, eofTruncated(err)
	}
	if n > MaxPayload {
		return 0, nil, errTooLarge
	}
	typ, err = readVaruint(r)
	if err != nil {
		return 0, nil, eofTruncated(err)
	}
	payload = make([]byte, n)
	if _, err := io.ReadFull(r, payload); err != nil {
		return 0, nil, eofTruncated(err)
	}
	return typ, payload, nil
}

func eofTruncated(err error) error {
	if err == io.EOF {
		return errTruncated
	}
	return err
}

func appendVaruint(b []byte, v uint32) []byte {
	for v >= 0x80 {
		b = append(b, byte(v)|0x80)
		v >>= 7
	}
	return append(b, byte(v))
}

// AppendFrame appends one plaintext frame to b.
func AppendFrame(b []byte, typ uint32, payload []byte) []byte {
	b = append(b, plaintextPreamble)
	b = appendVaruint(b, uint32(len(payload)))
	b = appendVaruint(b, typ)
	return append(b, payload...)
}
